import re


def normalize_phone(raw):
    text = re.sub(r"[ .\-()]", "", raw)
    match = re.fullmatch(r"\+?1?([0-9]{10})", text)
    if match is None:
        raise ValueError("not a US phone number: %r" % raw)
    return "+1" + match.group(1)

_TABLE = str.maketrans("", "", " .-()")


def normalize_phone(raw):
    text = raw.translate(_TABLE)
    if text[:1] == "+":
        text = text[1:]
    if not (text.isascii() and text.isdigit()):
        raise ValueError("not a US phone number: %r" % raw)
    if len(text) == 11 and text.startswith("1"):
        text = text[1:]
    if len(text) != 10:
        raise ValueError("not a US phone number: %r" % raw)
    return "+1{}".format(text)

