def wrap(text, width):
    result = []
    line = None
    for token in text.split():
        if line is None:
            line = token
            continue
        candidate = line + " " + token
        if len(candidate) <= width:
            line = candidate
        else:
            result.append(line)
            line = token
    if line is not None:
