                total += 1
    return total

from collections import Counter


def count_pairs(nums, target):
    freq = Counter(nums)
    total = 0
    for value, times in freq.items():
        other = target - value
        if other == value:
            total += times * (times - 1) // 2
        elif value < other and other in freq:
            total += times * freq[other]
    return total

def count_pairs(nums, target):
    counts = {}
    result = 0
    for x in nums:
        result += counts.get(target - x, 0)
        counts[x] = counts.get(x, 0) + 1
    return result

